args.content:
/* Halcyon Threshold - Simple, clean styling */

:root {
    --primary: #2c5282;
    --text: #1a202c;
    --text-light: #4a5568;
    --bg: #ffffff;
    --bg-alt: #f7fafc;
    --border: #e2e8f0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    line-height: 1.7;
    color: var(--text);
    background: var(--bg);
    max-width: 720px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

h1 {
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 0.5rem;
}

h2 {
    font-size: 1.25rem;
    font-weight: 600;
    margin-top: 2.5rem;
    margin-bottom: 1rem;
    color: var(--text);
}

.tagline {
    font-size: 1.1rem;
    color: var(--text-light);
    font-style: italic;
    margin-bottom: 2rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid var(--border);
}

.intro p {
    margin-bottom: 1rem;
}

section {
    margin-bottom: 2rem;
}

ul {
    margin-left: 1.5rem;
}

li {
    margin-bottom: 0.75rem;
}

a {
    color: var(--primary);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

footer {
    margin-top: 4rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border);
    color: var(--text-light);
    font-size: 0.875rem;
}

@media (max-width: 600px) {
    h1 {
        font-size: 2rem;
    }

    body {
        padding: 1.5rem 1rem;
    }
}
